'use strict';
(() => {
const go = document.getElementById('batchGo'); if (!go) return;
const input = document.getElementById('batchInput'), file = document.getElementById('batchFile'),
typeSel = document.getElementById('batchType'), st = document.getElementById('batchStatus');
file.addEventListener('change', () => {
const f = file.files[0]; if (!f) return;
const r = new FileReader(); r.onload = () => { input.value = String(r.result).split(/\r?\n/).map(l => l.split(',')[0].trim()).filter(Boolean).join('\n'); };
r.readAsText(f);
});
go.onclick = async () => {
const lines = input.value.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
if (!lines.length) { st.textContent = 'Paste at least one line first.'; return; }
if (lines.length > 500) { st.textContent = 'Max 500 per batch (keeps your browser happy).'; return; }
st.textContent = 'Loading ZIP engine…';
if (!window.JSZip) await new Promise((res, rej) => { const s = document.createElement('script'); s.src = '/vendor/jszip.min.js'; s.onload = res; s.onerror = rej; document.head.appendChild(s); });
const B = window.QRPayloads, zip = new window.JSZip(), type = typeSel.value;
let ok = 0;
qrcode.stringToBytes = qrcode.stringToBytesFuncs['UTF-8'];
for (const [i, line] of lines.entries()) {
let payload;
try { payload = type === 'url' ? B.url({ url: line }) : type === 'text' ? B.text({ text: line }) : type === 'wifi' ? B.wifi({ ssid: line, password: '', security: 'none' }) : type === 'phone' ? B.phone({ phone: line }) : B.sms({ phone: line, msg: '' }); }
catch { continue; }
try {
const q = qrcode(0, 'M'); q.addData(payload, 'Byte'); q.make();
const n = q.getModuleCount(), m = 4, tot = n + m * 2, px = 1024, cell = Math.max(1, Math.floor(px / tot));
const c = document.createElement('canvas'); c.width = c.height = cell * tot;
const x = c.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height); x.fillStyle = '#111';
for (let r = 0; r < n; r++) for (let col = 0; col < n; col++) if (q.isDark(r, col)) x.fillRect((col + m) * cell, (r + m) * cell, cell, cell);
const blob = await new Promise(r => c.toBlob(r));
zip.file(`qr-${type}-${String(i + 1).padStart(3, '0')}.png`, blob); ok++;
if (i % 25 === 0) st.textContent = `Rendering ${i + 1}/${lines.length}…`;
} catch {  }
}
st.textContent = `Zipping ${ok} codes…`;
const blob = await zip.generateAsync({ type: 'blob' });
const u = URL.createObjectURL(blob), a = document.createElement('a');
a.href = u; a.download = `qr-batch-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}.zip`;
document.body.appendChild(a); a.click(); a.remove();
setTimeout(() => URL.revokeObjectURL(u), 5000);
st.textContent = `✓ Done — ${ok}/${lines.length} codes zipped.`;
};
})();